INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23601, 'Mark 13:9', 'Mark', 13, 9, '&nbsp;خو تاسو بېدار اوسئ. تاسو به عدالتونو ته حواله کېږئ، تاسو به په عبادتخانو کښې په کوړو وهلے کېږئ، او تاسو به د حاکمانو او بادشاهانو په وړاندې زما په وجه پېش کولے شئ چې د هغوئ په وړاندې زما ګواهان شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23602, 'Mark 13:10', 'Mark', 13, 10, '&nbsp;خو د آخر وخت نه اول به زما د زيرى بيان ټولو قومونو ته وکړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23603, 'Mark 13:11', 'Mark', 13, 11, '&nbsp;خو هر کله چې تاسو ونيولے شئ او عدالت ته بوتلے شئ نو د اول نه تاسو مۀ پرېشانه کېږئ چې تاسو به څۀ وايئ. خو هر کله چې وخت راشى نو هغه وخت چې څۀ د وينا دپاره درکړے شى هغه وايئ، ځکه چې دا به ستاسو خبرې نۀ وى بلکې ستاسو په ژبه به روحُ القُدس ګويا وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23604, 'Mark 13:12', 'Mark', 13, 12, '&nbsp;ورور به د ورور د مرګ جاسوس شى او پلار به د زوئ، او اولاد به د مور پلار خلاف شى او مرګ ته به يې حواله کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23605, 'Mark 13:13', 'Mark', 13, 13, '&nbsp;ټول به زما د نوم په وجه تاسو نه نفرت کوى، خو هغه څوک چې تر آخره قائم پاتې شى هغه به بچ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23606, 'Mark 13:14', 'Mark', 13, 14, '&nbsp;هر کله چې تاسو ووينئ چې، هغه پليت بُت چې تباهى راولى په هغه ځائ کښې ولاړ دے چرته چې نۀ دے پکار، نو لوستونکى دې پوهه شى، نو هغه څوک چې په يهوديه کښې دى غرونو ته دې وتښتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23607, 'Mark 13:15', 'Mark', 13, 15, '&nbsp;کۀ څوک د چت دپاسه وى هغه دې کله هم کور ته ښکته نۀ راکوزيږى چې څۀ ترې وباسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23608, 'Mark 13:16', 'Mark', 13, 16, '&nbsp;کۀ څوک په پټى کښې وى نو هغه دې د خپلې چُوغې راخستلو دپاره نۀ واپس کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23609, 'Mark 13:17', 'Mark', 13, 17, '&nbsp;افسوس دے په هغه ښځو چې په هغه ورځو کښې اُميدوارې وى او په هغوئ چې بچو له سينه ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23610, 'Mark 13:18', 'Mark', 13, 18, '&nbsp;دُعا کوئ چې دا واقعه په ژمى کښې پېښه نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23611, 'Mark 13:19', 'Mark', 13, 19, '&nbsp;ځکه چې هغه به ډيرې د بد حالۍ ورځې وى. خُدائ پاک چې دا دُنيا پېدا کړې ده لا تر اوسه داسې وخت نۀ دے راغلے او نۀ به بيا چرته راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23612, 'Mark 13:20', 'Mark', 13, 20, '&nbsp;کۀ چرې مالِک خُدائ هغه د تکليف ورځې لنډې کړې نۀ وے نو هيڅ يو بشر به هم بچ شوے نۀ وے، خو د خپلو غوره کړو د خاطره هغۀ دا ورځې لنډې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23613, 'Mark 13:21', 'Mark', 13, 21, '&nbsp;او کۀ بيا تاسو ته په دغه وخت کښې څوک دا ووائى چې وګورئ، مسيح دلته دے يا هلته دے، نو باور پرې مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23614, 'Mark 13:22', 'Mark', 13, 22, '&nbsp;دروغژن مسيحيان او دروغژن نبيان به راښکاره شى او لوئې معجزې او نښې به ښکاره کوى، او کۀ ممکن وى نو غوره شوى خلق به بې‌لارې کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23615, 'Mark 13:23', 'Mark', 13, 23, '&nbsp;خو تاسو خبردار اوسئ، ما تاسو د اول نه په دې خبر کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23616, 'Mark 13:24', 'Mark', 13, 24, '&nbsp;خو په هغه ورځو کښې د دې تنګسيا نه پس به نمر تور شى او سپوږمۍ به رڼا نۀ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23617, 'Mark 13:25', 'Mark', 13, 25, '&nbsp;ستورى به د آسمان نه راپرېوځى او آسمانى طاقتونه به ولړزولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23618, 'Mark 13:26', 'Mark', 13, 26, '&nbsp;بيا به هغوئ ووينى چې اِبن آدم به په وريځو کښې په لوئ قدرت او ډېر شان او شوکت سره راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23619, 'Mark 13:27', 'Mark', 13, 27, '&nbsp;او هغه به فرښتې ولېږى او د آسمان د څلورو طرفونو نه او د دُنيا د آخرى حدونو نه به خپل غوره کړى خلق راټول کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23620, 'Mark 13:28', 'Mark', 13, 28, '&nbsp;د اينځر د ونې نه سبق زده کړئ. هر کله چې د هغې نازکې څانګې غوټۍ ونيسى او پاڼې وکړى نو تاسو پوهه شئ چې اوړے په راتلو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23621, 'Mark 13:29', 'Mark', 13, 29, '&nbsp;هم دغه شان چې تاسو دا ټولې نښې ووينئ نو تاسو پوهه شئ چې هغه ډېر نزدې او په دروازه کښې ولاړ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23622, 'Mark 13:30', 'Mark', 13, 30, '&nbsp;زۀ تاسو ته رښتيا وايم چې دا موجوده پيړۍ به تر هغې ختمه نۀ شى ترڅو چې دا ټولې خبرې ونۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23623, 'Mark 13:31', 'Mark', 13, 31, '&nbsp;زمکه او آسمان به فنا شى خو زما کلام به هيچرې فنا نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23624, 'Mark 13:32', 'Mark', 13, 32, '&nbsp;خو د هغې ورځې او ساعت هيچا ته پته نشته، نۀ خو د آسمان فرښتو ته پته شته او نۀ زوئ ته، خو صرف زما پلار پرې خبر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23625, 'Mark 13:33', 'Mark', 13, 33, '&nbsp;خبردار اوسئ، ويښ اوسئ. تاسو د دې نه خبر نۀ يئ چې هغه وخت به کله راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23626, 'Mark 13:34', 'Mark', 13, 34, '&nbsp;د دې مثال د هغه سړى په شان دے چې د کوره لرې روان وى او څۀ وخت چې خپل کور نه ځى نو خپلو نوکرانو ته اختيار ورکړى چې هر يو دې خپل کار کوى او څوکيدار ته هم حکم ورکړى چې بېدار اوسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23627, 'Mark 13:35', 'Mark', 13, 35, '&nbsp;نو بيا تاسو بېدار اوسئ ځکه چې تاسو په دې نۀ يئ خبر چې د کور مالِک به کله راځى، ماښام کۀ په نيمه شپه، په چرګ بانګ کۀ سحر په خړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23628, 'Mark 13:36', 'Mark', 13, 36, '&nbsp;کۀ چرې هغه ناګهانه راشى نو چې هغه مو اودۀ لاندې نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23629, 'Mark 13:37', 'Mark', 13, 37, '&nbsp;او زۀ چې څۀ تاسو ته وايم نو هغه ټولو ته وايم چې بېدار اوسئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23630, 'Mark 14:1', 'Mark', 14, 1, '&nbsp;د فسح او د پتيرې روټۍ اختر ته دوه ورځې پاتې وې او مشرانو اِمامانو او د شرعې عالمانو داسې طريقه لټوله چې عيسىٰ په پټه ونيسى او وې وژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23631, 'Mark 14:2', 'Mark', 14, 2, '&nbsp;هغوئ ووئيل چې، ”دا دې د اختر په ورځو کښې نۀ وى، هسې نه چې په خلقو کښې بلوا جوړه شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23632, 'Mark 14:3', 'Mark', 14, 3, '&nbsp;عيسىٰ د شمعون جذامى په کور کښې په بيتِ‌عنياه کښې وو. کله چې هغه روټۍ ته کښېناستو، نو يوه ښځه راغله او ډېر قيمتى خالص عطر يې د مرمرو په عطردان کښې راوړل. هغې د عطردان سر مات کړو او د هغۀ په سر يې عطر واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23633, 'Mark 14:4', 'Mark', 14, 4, '&nbsp;په حاضر مجلس کښې ځينې کسانو په غصه کښې ووئيل چې، ”دا قيمتى عطر ولې ضائع شول؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23634, 'Mark 14:5', 'Mark', 14, 5, '&nbsp;ځکه چې دا عطر خو به په څۀ دپاسه د درېو سوو دينارو خرڅ شوے وے او پېسې به يې خوارانو له ورکړے شوے وے.“ نو هغوئ هغې ته غصه وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23635, 'Mark 14:6', 'Mark', 14, 6, '&nbsp;خو عيسىٰ ورته وفرمائيل، ”دا پرېږدئ، تاسو دا ښځه ولې تنګوئ؟ هغې زما ډېر ښۀ خِدمت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23636, 'Mark 14:7', 'Mark', 14, 7, '&nbsp;ځکه چې غريبانان خو به تل تاسو سره وى او هر کله چې تاسو غواړئ د هغوئ مدد کولے شئ خو زۀ به درسره تل نۀ يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23637, 'Mark 14:8', 'Mark', 14, 8, '&nbsp;هغې نه چې څۀ کېدے شول، هغه يې وکړل. هغې د ښخولو نه وړاندې زما په بدن عطر واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23638, 'Mark 14:9', 'Mark', 14, 9, '&nbsp;زۀ تاسو ته رښتيا وايم چې هر چرته چې په دُنيا کښې دا زېرے خوريږى نو څۀ چې هغې وکړل نو دا به هم په کښې ياديږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23639, 'Mark 14:10', 'Mark', 14, 10, '&nbsp;نو بيا يهوداه اِسکريوتى چې په هغه دولسو مريدانو کښې يو وو، مشرانو اِمامانو له لاړو چې د عيسىٰ مخبرى وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23640, 'Mark 14:11', 'Mark', 14, 11, '&nbsp;چې هغوئ د هغۀ د غرض نه خبر شول نو هغوئ ډېر خوشحاله شول او د هغۀ سره يې د پېسو ورکولو وعده وکړه. د هغه وخت نه پس هغه د مخبرۍ د موقعې په تلاش کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23641, 'Mark 14:12', 'Mark', 14, 12, '&nbsp;د پتيرې روټۍ د اختر په اوله ورځ چې هغوئ د فسح ګډورے قربانولو، د عيسىٰ مريدانو د هغۀ نه تپوس وکړو چې، ”ستا کوم ځائ خوښ دے چې مونږ په کښې تا له د فسح خوراک تيار کړُو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23642, 'Mark 14:13', 'Mark', 14, 13, '&nbsp;نو هغۀ خپل دوه مريدان د دې هداياتو سره ولېږل، ”ښار ته لاړ شئ، يو سړے به ووينئ چې د اوبو منګے به وړى، په هغۀ پسې لاړ شئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23643, 'Mark 14:14', 'Mark', 14, 14, '&nbsp;او هغه چې کوم کور ته ننوځى نو د هغه کور مالِک له دا پېغام ورکړئ چې، اُستاذ وائى چې زما او زما د مريدانو دپاره د فسح د خوراک دپاره د مېلمستيا کومه کوټه مقرره شوې ده؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23644, 'Mark 14:15', 'Mark', 14, 15, '&nbsp;هغه به تاسو ته يوه لويه تياره کړے شوې بالاخانه وښائى، زمونږ دپاره هلته د فسح تيارے وکړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23645, 'Mark 14:16', 'Mark', 14, 16, '&nbsp;بيا مريدان روان شول او چې ښار ته دننه شول نو هغوئ هر څۀ هغه شان وموندل څنګه چې هغۀ ورته فرمائيلى وُو، نو هغوئ د فسح د خوراک تيارے وکړلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23646, 'Mark 14:17', 'Mark', 14, 17, '&nbsp;کله چې ماښام شو نو هغه د دولسو مريدانو سره راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23647, 'Mark 14:18', 'Mark', 14, 18, '&nbsp;څۀ وخت چې هغوئ روټۍ ته کښېناستل نو عيسىٰ وفرمائيل، ”زۀ درته رښتيا وايم چې په تاسو کښې به يو زما مُخبرى کوى، هغه څوک چې ما سره روټۍ خورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23648, 'Mark 14:19', 'Mark', 14, 19, '&nbsp;په ډيرې پرېشانۍ سره هغوئ يو يو ورته ووئيل، ”رښتيا زۀ خو به نۀ يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23649, 'Mark 14:20', 'Mark', 14, 20, '&nbsp;هغۀ ورته وفرمائيل چې، ”په تاسو دولسو کښې هغه يو دے څوک چې ما سره په دې تالى کښې لاس ښکته کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23650, 'Mark 14:21', 'Mark', 14, 21, '&nbsp;د اِبن آدم په حق کښې چې په صحيفو کښې څۀ راغلى دى هغه به په هغه لاره ځى، خو افسوس په هغه سړى دے چې په اِبن آدم مُخبرى کوى. کۀ هغه سړے پېدا شوے نۀ وے نو دا به ډېره ښۀ وه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23651, 'Mark 14:22', 'Mark', 14, 22, '&nbsp;د خوراک په وخت عيسىٰ يوه روټۍ راواخسته، شُکر يې پرې وکړو او ماته يې کړه. په هغوئ يې وويشله او وې فرمائيل، ”دا واخلئ، دا زما بدن دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23652, 'Mark 14:23', 'Mark', 14, 23, '&nbsp;بيا هغۀ يوه پيالۍ راواخسته او د خُدائ پاک شُکر يې پرې وويستو او هغوئ له يې ورکړه او هغوئ ټولو ترې وڅښل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23653, 'Mark 14:24', 'Mark', 14, 24, '&nbsp;او بيا هغۀ هغوئ ته وفرمائيل چې، ”دا زما وينه ده چې د خُدائ پاک او د انسانانو تر مينځ د لوظ نښه ده چې د ډېرو خلقو دپاره توئيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23654, 'Mark 14:25', 'Mark', 14, 25, '&nbsp;زۀ تاسو ته رښتيا وايم چې د انګورو رس به زۀ بيا تر هغې ورځې پورې ونۀ څښم ترڅو چې زۀ د خُدائ پاک په بادشاهۍ کښې يې تازه ونۀ څښم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23655, 'Mark 14:26', 'Mark', 14, 26, '&nbsp;د حمد وئيلو نه پس دوئ د زيتُونو غرۀ ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23656, 'Mark 14:27', 'Mark', 14, 27, '&nbsp;او عيسىٰ هغوئ ته وفرمائيل، ”تاسو ټول به تيندک وخورئ ځکه چې دا ليکلے شوى دى چې، ”زۀ به شپون ووهم او ګډې به يې خورې ورې شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23657, 'Mark 14:28', 'Mark', 14, 28, '&nbsp;خو هر کله چې زۀ بيا ژوندے پاڅولے شم نو زۀ به ستاسو نه وړاندې ګليل ته لاړ شم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23658, 'Mark 14:29', 'Mark', 14, 29, '&nbsp;پطروس جواب ورکړو، ”کۀ چرې دوئ ټول تيندک وخورى، خو زۀ به هيچرې تيندک ونۀ خورم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23659, 'Mark 14:30', 'Mark', 14, 30, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”زۀ تا ته رښتيا وايم چې تۀ به نن په هم دې شپه د دوېم چرګ بانګ وئيلو نه وړاندې درې ځله زما نه اِنکارى شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23660, 'Mark 14:31', 'Mark', 14, 31, '&nbsp;خو هغۀ په دې خبره زور ورکړو، ”کۀ زۀ تا سره مړ هم شم خو ستا نه به هيچرې اِنکارى نۀ شم.“ او هغوئ ټولو هم دغه شان ووئيل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23661, 'Mark 14:32', 'Mark', 14, 32, '&nbsp;کله چې هغوئ ګيتسمنى نومې ځائ ته ورسېدل نو عيسىٰ خپلو مريدانو ته وفرمائيل، ”ترڅو چې زۀ دُعا کوم تاسو دلته کښېنئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23662, 'Mark 14:33', 'Mark', 14, 33, '&nbsp;او هغۀ بيا د ځان سره پطروس، يعقوب او يوحنا بوتلل، نو ډېر غمژن شو او پرېشانى پرې راغله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23663, 'Mark 14:34', 'Mark', 14, 34, '&nbsp;او هغوئ ته يې وفرمائيل چې، ”زما زړۀ د غمه چوى او مرګ ته نزدې شوے يم. دلته ايسار شئ او ما سره بېدار اوسئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23664, 'Mark 14:35', 'Mark', 14, 35, '&nbsp;بيا هغه يو څو قدمه لاړو، او په زمکه پړمخې پرېوتو او دا دُعا يې وغوښتله، ”کۀ دا کېدے شى نو دا سخت وخت دې له ما نه لرې کړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23665, 'Mark 14:36', 'Mark', 14, 36, '&nbsp;هغۀ وفرمائيل، ”ابا،“ يعنې پلاره، ”ستا دپاره هر څۀ ممکن دى. دا د تکليف پياله زما نه اخوا کړه، خو زما مرضى نه بلکې ستا مرضى دې پوره شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23666, 'Mark 14:37', 'Mark', 14, 37, '&nbsp;هغه واپس راغلو او هغوئ يې اودۀ وموندل. نو هغۀ پطروس ته وفرمائيل، ”شمعونه، اودۀ يې څۀ؟ ولې تاسو ما سره يوه ګينټه قدرې هم بېدار نۀ شوئ پاتې کېدے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23667, 'Mark 14:38', 'Mark', 14, 38, '&nbsp;بېدار شئ، او دُعا وکړئ چې د آزمېښت په وخت ناکامه نۀ شئ. ځکه چې روح خو تيار دے خو بدن کمزورے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23668, 'Mark 14:39', 'Mark', 14, 39, '&nbsp;يو ځل بيا هغه لاړو او هم هغه شان دُعا يې وغوښته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23669, 'Mark 14:40', 'Mark', 14, 40, '&nbsp;چې يو ځل بيا هغه واپس راغلو نو هغوئ يې اودۀ وموندل ځکه چې د هغوئ سترګې درنې شوې وې، او هغوئ په دې نۀ پوهېدل چې هغۀ ته څۀ جواب ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23670, 'Mark 14:41', 'Mark', 14, 41, '&nbsp;درېم ځل هغه راغلو او ورته يې وفرمائيل چې، ”ولې تاسو لا هغه شان اودۀ يئ، هغه شان لا آرام کوئ؟ بس، هغه وخت راغلو چې اِبن آدم د ګناهګارانو لاسونو ته وسپارلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23671, 'Mark 14:42', 'Mark', 14, 42, '&nbsp;پاڅئ، ځئ چې ځو. زما مُخبر نزدې راغلے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23672, 'Mark 14:43', 'Mark', 14, 43, '&nbsp;عيسىٰ چې لا خبرې کولې نو سمدستى يهوداه چې په دولسو مريدانو کښې يو وو راغلو، او هغۀ سره ډېر خلق چې تُورې او کوتکې په لاس وُو راښکاره شول. هغوئ مشرانو اِمامانو، د شرعې عالمانو او اولسى مشرانو رالېږلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23673, 'Mark 14:44', 'Mark', 14, 44, '&nbsp;جاسوس هغوئ ته دا نښه ښودلې وه، ”څوک چې زۀ ښکل کړم هم هغه دے، وې نيسئ او د ځان سره يې په حفاظت بوځئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23674, 'Mark 14:45', 'Mark', 14, 45, '&nbsp;کله چې دے هغه ځائ ته راورسېدو نو هغه سمدستى وروړاندې شو او عيسىٰ ته يې ووئيل، ”اُستاذه.“ او ښکل يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
