(23678, 'Mark 14:49', 'Mark', 14, 49, '&nbsp;زۀ هره ورځ تاسو سره د خُدائ په کور کښې وم او تعليم مې ورکولو خو تاسو ما له لاس نۀ راوړلو. خو دا ځکه وشول چې د نبيانو صحيفې پوره شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23679, 'Mark 14:50', 'Mark', 14, 50, '&nbsp;نو بيا ټولو مريدانو هغه يواځې پرېښودو او ترې وتښتېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
