(23681, 'Mark 14:52', 'Mark', 14, 52, '&nbsp;خو هغۀ د کتان څادر پرېښودلو او لغړ وتښتېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
