(23691, 'Mark 14:62', 'Mark', 14, 62, '&nbsp;عيسىٰ وفرمائيل چې، ”زۀ يم، او تاسو به اِبن آدم د خُدائ پاک ښى لاس ته سره د اختيار ناست او د آسمان په وريځو کښې په راتلو ووينئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23692, 'Mark 14:63', 'Mark', 14, 63, '&nbsp;په دې وينا مشر اِمام خپله چُوغه وشلوله او وې وئيل چې، ”دے خو کُفر وائى. د دې ګستاخۍ نه پس هم د نورو ګواهانو حاجت شته څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23693, 'Mark 14:64', 'Mark', 14, 64, '&nbsp;تاسو په خپله دا کُفر واورېدو ستاسو فېصله څۀ ده؟“ هغوئ جواب ورکړو چې، ”دے مجرم دے او د مرګ جوګه دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
